#pragma once
#include "buyer_demand.hpp"
namespace perekup {
inline Json& nativeCollectorState(Json& state){auto& s=state["bank"]["collectors"];if(!s.is_object()||s.value("version",0)!=1)s={{"version",1},{"active",false},{"loanIds",Json::array()},{"level",0},{"nextEventAt",nullptr},{"sequence",0},{"call",nullptr},{"log",Json::array()}};return s;}
inline void nativeCollectorLog(Json& state,const std::string& kind,const std::string& text){auto& s=nativeCollectorState(state);auto sequence=s.value("sequence",0LL)+1;s["sequence"]=sequence;Json entry={{"id",sequence},{"when",state.at("gameMs")},{"kind",kind},{"text",text}};s["log"].insert(s["log"].begin(),entry);if(s["log"].size()>60)s["log"].erase(s["log"].begin()+60,s["log"].end());state["bank"]["revision"]=num(state["bank"],"revision")+1;}
inline void syncNativeCollectors(Json& state){auto& s=nativeCollectorState(state);Json ids=Json::array();double oldest=num(state,"gameMs"),now=oldest;for(const auto& l:state["bank"]["loans"])if(Bank::overdueCents(l)>0&&l.contains("overdueAt")&&l["overdueAt"].is_number()&&now-num(l,"overdueAt")>=collectorGrace){ids.push_back(l.at("id"));oldest=std::min(oldest,num(l,"overdueAt"));}std::sort(ids.begin(),ids.end());int level=ids.empty()?0:now-oldest>=180*day?3:now-oldest>=120*day?2:1;bool was=s.value("active",false);bool changed=s["level"]!=level||s["loanIds"]!=ids;s["active"]=level>0;s["level"]=level;s["loanIds"]=ids;if(level&&(!was||s["nextEventAt"].is_null())){s["nextEventAt"]=now+30*60000;changed=true;if(!was)nativeCollectorLog(state,"started","Просрочка достигла 30 дней. Долг передан игровому отделу взыскания.");}if(!level){s["call"]=nullptr;s["nextEventAt"]=nullptr;if(was)nativeCollectorLog(state,"stopped","Длительная просрочка погашена. Коллекторы прекратили звонки и помехи.");}if(changed)state["bank"]["revision"]=num(state["bank"],"revision")+1;}
inline double nativeCollectorEventDelay(int level,const std::function<double()>& random){return jsRound((6+std::floor(random()*7))*3600000/(level==3?2:level==2?1.5:1));}
inline void tickNativeCollectors(Json& state,const std::function<double()>& random,bool busy=false){
 Json draft=state;syncNativeCollectors(draft);auto& s=nativeCollectorState(draft);double now=num(draft,"gameMs");
 if(!s.value("active",false)||busy||!s["call"].is_null()||now<num(s,"nextEventAt")){state.swap(draft);return;}
 int level=s.at("level");s["nextEventAt"]=now+nativeCollectorEventDelay(level,random);double event=random();
 auto message=[&]{static const char* lines[]={"Отдел взыскания: длительная просрочка сохраняется. Требуем погасить её в приложении «Банк».","Коллектор снова написал: «Платёж так и не поступил. Когда закроете просрочку?»","Новое напоминание от взыскателей: «Договорённости о погашении нет. Мы снова свяжемся с вами.»"};nativeCollectorLog(draft,"message",lines[std::min(2,int(random()*3))]);};
 if(event<.45){static const char* names[]={"Олег","Денис","Светлана"};static const char* lines[]={"Мы снова по поводу вашей просрочки. Когда поступит платёж? Давайте разберёмся сейчас.","Просрочка не закрыта. Требуем погасить задолженность — открывайте Банк.","Обещаниями долг не закрыть. Обсудим, когда вы вернёте просроченную сумму."};auto seq=s.value("sequence",0LL)+1;s["sequence"]=seq;auto name=std::string(names[std::min(2,int(random()*3))]);int minutes=int(15+std::floor(random()*16))*level;s["call"]={{"id",seq},{"name",name},{"minutes",minutes},{"text",lines[std::min(2,int(random()*3))]},{"when",now}};nativeCollectorLog(draft,"call","Звонок взыскателя "+name+": разговор на "+std::to_string(minutes)+" игровых минут.");}
 else if(event<.70)message();
 else if(event<.85){std::vector<std::size_t> offers;auto& pending=draft["pending"];for(std::size_t i=0;i<pending.size();++i)if(pending[i].value("type","")=="ad"&&pending[i].value("ready",false))offers.push_back(i);if(offers.empty())message();else{auto index=offers.at(std::min(offers.size()-1,std::size_t(random()*offers.size())));auto offer=pending[index];auto id=offer.at("id");pending.erase(pending.begin()+index);for(auto it=draft["chatStore"].begin();it!=draft["chatStore"].end();)if(it.value().value("pid",Json(nullptr))==id)it=draft["chatStore"].erase(it);else ++it;if(draft.contains("chat")&&draft["chat"].is_object()&&draft["chat"].value("pid",Json(nullptr))==id){draft["chat"]["done"]=true;draft["chat"]["stage"]="done";draft["chat"]["pid"]=nullptr;}nativeCollectorLog(draft,"buyer",offer.at("npc").value("name","")+" отказался от переговоров: звонки взыскателей отпугнули покупателя.");}}
 else{bool delayed=false;for(auto& p:draft["pending"])if(p.value("type","")=="meet"&&p.contains("flow")&&p["flow"].is_object()&&p["flow"].value("stage","")=="waiting"&&!p["flow"].value("collectorDelayed",false)){int minutes=int(15+std::floor(random()*31))*level;auto& f=p["flow"];f["arrivalAt"]=num(f,"arrivalAt")+minutes*60000;f["inspectionUntil"]=num(f,"inspectionUntil")+minutes*60000;f["collectorDelayed"]=true;f["collectorDelayMinutes"]=minutes;nativeCollectorLog(draft,"meeting","Коллекторы вмешались в переговоры. Вторая сторона задерживается на "+std::to_string(minutes)+" игровых минут.");delayed=true;break;}if(!delayed)message();}
 state.swap(draft);
}
// Advance the rest of the game in 15-minute steps while collector events are
// suppressed; caller persists this entire draft before committing UI success.
inline bool dismissNativeCollectorCall(Json& state,const std::function<void(Json&,Money)>& advance,const std::function<double()>& random){Json draft=state;auto& s=nativeCollectorState(draft);if(s["call"].is_null())return false;Money until=Money(num(draft,"gameMs"))+s["call"].at("minutes").get<Money>()*60000;s["call"]=nullptr;while(num(draft,"gameMs")<until){Money next=std::min(until,Money(num(draft,"gameMs"))+15*60000);advance(draft,next);if(num(draft,"gameMs")!=next)throw std::logic_error("Clock advance did not reach requested time");}syncNativeCollectors(draft);auto& current=nativeCollectorState(draft);if(current.value("active",false))current["nextEventAt"]=std::max(num(current,"nextEventAt"),num(draft,"gameMs")+nativeCollectorEventDelay(current.at("level"),random));state.swap(draft);return true;}
}
